package com.silverroom.camera;

public final class CameraShaders {
    private CameraShaders(){}
    public static final String VERTEX="attribute vec2 aP;attribute vec2 aT;uniform mat4 uM;uniform mat4 uST;uniform float uCrop;varying vec2 vT;varying vec2 vP;varying vec2 vF;varying vec2 vDX;varying vec2 vDY;void main(){gl_Position=uM*vec4(aP,0.,1.);vT=(uST*vec4((aT-.5)/uCrop+.5,0.,1.)).xy;vP=aT;vF=gl_Position.xy*.5+.5;float det=uM[0][0]*uM[1][1]-uM[1][0]*uM[0][1];vec2 dx=vec2(uM[1][1],-uM[0][1])*.012/(det*uCrop);vec2 dy=vec2(-uM[1][0],uM[0][0])*.012/(det*uCrop);vDX=(uST*vec4(dx,0.,0.)).xy;vDY=(uST*vec4(dy,0.,0.)).xy;}";
    private static final String PRECISION="#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\n";
    private static final String UNIFORMS=PRECISION+"uniform sampler2D uGrain;uniform vec3 uGain;uniform vec3 uLift;uniform vec4 uTone;uniform vec3 uShadow;uniform vec3 uHighlight;uniform vec3 uPost;uniform vec4 uFx;uniform vec2 uMix;uniform vec2 uQuality;uniform float uShoulder;varying vec2 vT;varying vec2 vP;varying vec2 vF;varying vec2 vDX;varying vec2 vDY;";
    private static final String SAMPLE="vec3 neighbor(vec2 o){vec2 d=(clamp(vF+o*.012,0.,1.)-vF)/.012;return source(vT+vDX*d.x+vDY*d.y);}void main(){vec3 original=source(vT);if(uMix.x<=0.){gl_FragColor=vec4(clamp(original*uMix.y,0.,1.),1.);return;}vec3 c=original;if(uFx.y>0.){float mask=smoothstep(.12,.42,abs(vF.y-.5))*uFx.y;if(mask>0.){vec3 blur=c*4.+(neighbor(vec2(-1.,0.))+neighbor(vec2(1.,0.))+neighbor(vec2(0.,-1.))+neighbor(vec2(0.,1.)))*2.+neighbor(vec2(-1.,-1.))+neighbor(vec2(-1.,1.))+neighbor(vec2(1.,-1.))+neighbor(vec2(1.,1.));c=mix(c,blur/16.,mask);}}";
    private static final String FILM="c=(c-.5)*uTone.y+.5;c=c*uGain+uLift;c=c*(1.-uTone.z*.35)+uTone.z*.16;vec3 k=clamp(c,0.,1.);c+=uShadow*(1.-k)*(1.-k)+uHighlight*k*k;vec3 hi=max(c-.65,0.);c=mix(c,vec3(.65)+hi/(1.+uShoulder*hi),step(vec3(.65),c));float l=dot(c,vec3(.299,.587,.114));c=mix(vec3(l),c,uTone.x)*uPost;vec2 q=vF*2.-1.;c*=1.-uFx.z*dot(q,q);float spread=original.r-original.b;float skin=(original.r>original.g&&original.g>original.b&&original.r-original.g<=.35&&original.g-original.b<=.30&&spread>=.03)?clamp((min(original.r,1.)-.12)/.28,0.,1.)*clamp((.65-spread)/.3,0.,1.):0.;c=mix(c,original,skin*uQuality.x*step(.001,uTone.x));if(uTone.w>0.){float n=texture2D(uGrain,(floor(gl_FragCoord.xy)+.5)/512.).r-.5;float shade=smoothstep(.08,.50,dot(c,vec3(.299,.587,.114)));c+=n*uTone.w*.156862745*mix(1.,.35+.65*shade,uQuality.y);}c=clamp(c,0.,1.);if(uFx.x>0.){float a=max(0.,1.-vF.x/.42),b=max(0.,1.-(1.-vF.x)/.20);float leak=uFx.x*(a*a*a+.30*b*b*b)*(.8+.2*(1.-2.*abs(vF.y-.5)));c=1.-(1.-c)*(1.-vec3(.85,.28,.09)*leak);}if(uFx.w>0.)c=floor(clamp(c,0.,1.)*uFx.w+.5)/uFx.w;gl_FragColor=vec4(mix(clamp(original*uMix.y,0.,1.),clamp(c,0.,1.),uMix.x),1.);}";
    public static final String EXTERNAL="#extension GL_OES_EGL_image_external : require\n"+UNIFORMS+"uniform samplerExternalOES uTex;vec3 source(vec2 t){return texture2D(uTex,clamp(t,0.,1.)).rgb;}"+SAMPLE+FILM;
    public static final String YUV=UNIFORMS+"uniform sampler2D uY;uniform sampler2D uVU;vec3 source(vec2 tc){vec2 t=clamp(vec2(tc.x,1.-tc.y),0.,1.);float y=1.164383*(texture2D(uY,t).r-.0627451);vec4 vu=texture2D(uVU,t);float v=vu.r-.5;float u=vu.a-.5;return clamp(vec3(y+1.596027*v,y-.391762*u-.812968*v,y+2.017232*u),0.,1.);}"+SAMPLE+FILM;
    // Popup-only clean source; never sample the already filtered screen framebuffer.
    public static final String RAW_EXTERNAL="#extension GL_OES_EGL_image_external : require\n"+PRECISION+"uniform samplerExternalOES uTex;varying vec2 vT;void main(){gl_FragColor=vec4(texture2D(uTex,vT).rgb,1.);}";
    public static final String RAW_YUV=PRECISION+"uniform sampler2D uY;uniform sampler2D uVU;varying vec2 vT;void main(){vec2 t=vec2(vT.x,1.-vT.y);float y=1.164383*(texture2D(uY,t).r-.0627451);vec4 vu=texture2D(uVU,t);float v=vu.r-.5;float u=vu.a-.5;gl_FragColor=vec4(clamp(vec3(y+1.596027*v,y-.391762*u-.812968*v,y+2.017232*u),0.,1.),1.);}";
}



